package io.github.jesterportfolio.hearth.persistence;

import java.sql.*;import java.util.*;import java.util.concurrent.*;import javax.sql.DataSource;
import io.github.jesterportfolio.hearth.economy.*;import io.github.jesterportfolio.hearth.inventory.*;
import io.github.jesterportfolio.hearth.survival.platform.JobPolicy;

public final class JobsDatabaseChecks {
    private static <T>T await(CompletionStage<T> s)throws Exception{return s.toCompletableFuture().get(12,TimeUnit.SECONDS);}
    private static void reject(CompletionStage<?> s)throws Exception{try{await(s);throw new IllegalStateException("EXPECTED_REJECTION");}catch(ExecutionException expected){}}
    private static void check(boolean b,String name){if(!b)throw new IllegalStateException(name);System.out.println("HEARTH_JOBS_DB_CHECK PASS "+name);System.out.flush();}
    public static void run(DataSource source,Connection c)throws Exception{
        var props=new Properties();try(var in=JobsDatabaseChecks.class.getResourceAsStream("/economy-demo.properties")){props.load(in);}props.setProperty("fixture-balance","0");var db=PostgresProgressStore.forModules(source,f->{});var economy=new EconomyStore(db,EconomyContent.parse(props));await(economy.migrate());await(economy.migrate());UUID realm=UUID.randomUUID();await(economy.openNativeRealm(realm,UUID.randomUUID(),"a".repeat(64),1,true));var store=new JobStore(db,economy,realm);var ctx=economy.context(realm,UUID.randomUUID());var empty=InventoryPayload.pack(new byte[41][]);await(economy.ensureAccount(ctx,empty));var original=await(economy.account(ctx));check(true,"E013_is_idempotent_and_original_migration_checksums_are_retained");
        var intervals=new TreeMap<String,Long>();for(String role:JobPolicy.ROLES)intervals.put(role,role.equals("novice")?1L:0L);var schedule=await(store.configure(intervals,10)).schedules().stream().filter(s->s.target().equals("novice")).findFirst().orElseThrow();check(schedule.next()==11&&await(store.snapshot()).schedules().equals(await(store.snapshot()).schedules()),"logical_clock_does_not_advance_schedule_while_server_is_offline");
        reject(store.reserve(ctx,UUID.randomUUID(),"resource_reset","novice",Map.of("seed","42"),10,schedule));check(await(store.snapshot()).jobs().isEmpty(),"early_or_stale_schedule_cannot_create_job");
        UUID id=UUID.randomUUID();var first=store.reserve(ctx,id,"resource_reset","novice",Map.of("seed","42"),11,schedule);var second=store.reserve(ctx,UUID.randomUUID(),"resource_reset","novice",Map.of("seed","43"),11,schedule);var jobs=new ArrayList<JobStore.Job>();for(var work:List.of(first,second))try{jobs.add(await(work).job());}catch(ExecutionException expected){}check(jobs.size()==1&&await(store.snapshot()).active().isPresent(),"concurrent_due_claims_start_exactly_one_job");var running=jobs.getFirst();var replay=await(store.reserve(ctx,running.id(),running.kind(),running.target(),running.arguments(),running.tick(),schedule));check(replay.replay()&&replay.job().arguments().equals(running.arguments()),"same_request_replays_fixed_arguments_without_authorizing_execution");reject(store.reserve(ctx,running.id(),running.kind(),running.target(),Map.of("seed","999"),11,schedule));check(true,"same_request_cannot_reroll_or_replace_saved_seed");
        var changed=new TreeMap<>(intervals);changed.put("novice",2L);reject(store.configure(changed,11));check(await(store.snapshot()).schedules().contains(schedule),"configuration_change_is_refused_while_job_result_is_unresolved");reject(store.reserve(new ServerProgressAccess().forVerifiedServerLink(realm,ctx.playerId()),UUID.randomUUID(),"resource_reset","end",Map.of("seed","42"),11,null));check(true,"foreign_context_issuer_cannot_submit_job");
        var recovered=await(store.recover());var held=recovered.active().orElseThrow();check(held.state()==JobStore.State.HOLD&&held.id().equals(running.id())&&held.arguments().equals(running.arguments())&&await(store.recover()).active().orElseThrow().equals(held),"restart_moves_running_job_to_idempotent_HOLD_without_reexecution");reject(store.finish(running,JobStore.State.SUCCEEDED,"stale",15));var forged=new JobStore.Job(held.id(),held.kind(),"end",held.arguments(),held.tick(),held.scheduled(),held.state(),held.revision(),held.message());reject(store.finish(forged,JobStore.State.SUCCEEDED,"forged",15));check(true,"stale_revision_or_changed_job_identity_cannot_confirm_result");
        try(var s=c.createStatement()){s.execute("CREATE FUNCTION hearth_economy.reject_job_fixture() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'job fixture failure' USING ERRCODE='23514'; END $$");s.execute("CREATE TRIGGER reject_job_fixture BEFORE UPDATE ON hearth_economy.platform_job FOR EACH ROW EXECUTE FUNCTION hearth_economy.reject_job_fixture()");}reject(store.finish(held,JobStore.State.SUCCEEDED,"test",15));check(await(store.snapshot()).active().orElseThrow().equals(held)&&await(store.snapshot()).schedules().contains(schedule),"SQL_failure_preserves_job_and_next_schedule_atomically");try(var s=c.createStatement()){s.execute("DROP TRIGGER reject_job_fixture ON hearth_economy.platform_job");s.execute("DROP FUNCTION hearth_economy.reject_job_fixture()");}
        var done=await(store.finish(held,JobStore.State.SUCCEEDED,"confirmed",100));var next=await(store.snapshot()).schedules().stream().filter(s->s.target().equals("novice")).findFirst().orElseThrow();check(done.state()==JobStore.State.SUCCEEDED&&next.next()==101,"successful_reconciliation_skips_backlog_and_waits_one_new_interval");reject(store.finish(done,JobStore.State.HOLD,"retry",101));check(true,"terminal_job_cannot_be_returned_to_running_or_hold");
        var manual=await(store.reserve(ctx,UUID.randomUUID(),"resource_reset","end",Map.of("seed","42"),100,null));await(store.finish(manual.job(),JobStore.State.CANCELLED,"not started",100));check(await(store.snapshot()).active().isEmpty(),"explicit_cancellation_preserves_history_and_releases_dispatch_slot");
        UUID otherRealm=UUID.randomUUID();await(economy.openNativeRealm(otherRealm,UUID.randomUUID(),"b".repeat(64),1,true));var other=new JobStore(db,economy,otherRealm);check(await(other.inspect(done.id())).isEmpty()&&await(economy.account(ctx)).equals(original),"job_queries_are_realm_scoped_and_do_not_change_wallet_or_inventory");
        String hash;try(var s=c.createStatement();var r=s.executeQuery("SELECT checksum FROM hearth_economy.version WHERE version=13")){r.next();hash=r.getString(1);}try(var s=c.createStatement()){s.execute("UPDATE hearth_economy.version SET checksum='jobs-fixture-mismatch' WHERE version=13");}reject(economy.migrate());try(var s=c.prepareStatement("UPDATE hearth_economy.version SET checksum=? WHERE version=13")){s.setString(1,hash);s.executeUpdate();}check(await(store.inspect(done.id())).orElseThrow().equals(done),"schema_checksum_mismatch_cannot_reinitialize_job_history");await(db.closeAsync());
    }
}
